import { useParms } from "react-router";
export default function Product() {
  const { id } = useParms();

  const [product, setProduct] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const getProduct = async () => {
      setLoading(true);
      const response = await fetch(`https://fakestoreapi.com/products/${id3}`);
      setProduct(await response.json());
      setLoading(false);
    };
    getProduct();
  }, []);
